# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        self.assertEqual(
            round_span(Span(542, 1026), 15), Span(540, 1020)
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(Span(45, 105), 30), Span(60, 120)
        )

    def test_end_of_day_stays(self):
        self.assertEqual(
            round_span(Span(1400, 1440), 30),
            Span(1410, 1440),
        )

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:13")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-12:00"), Span(780, 1020)]
        self.assertEqual(
            rounded_labels(spans, 60),
            [
                "08:00-12:00 (4h 00m)",
                "13:00-17:00 (4h 00m)",
            ],
        )

    def test_empty(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(61, 64)], 15)

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)
                with self.assertRaises(ValueError):
                    round_span(Span(60, 120), step)

    def test_bad_step_raises_for_empty_input(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)
